1	// Basket rules, free of Hono and of file I/O: the store and the catalog come in as values.
2	import type { AddBasketItem, BasketLine, BasketResponse, StoredBasket } from "@organic/shared";
3	import type { CatalogService } from "./catalog";
4	import type { BasketStore } from "./store/baskets";
5	
6	const MAX_QUANTITY = 99;
7	
8	/** A miss is a value, not an exception: the route maps it to 404 without a try/catch. */
9	export type BasketResult =
10	  | { ok: true; basket: BasketResponse }
11	  | { ok: false; error: "Product not found" | "Basket item not found" };
12	
13	export interface BasketServiceOptions {
14	  store: BasketStore;
15	  catalog: Pick<CatalogService, "findProduct">;
16	  now: () => number;
17	}
18	
19	export interface BasketService {
20	  get(id: string): Promise<BasketResponse>;
21	  addItem(id: string, item: AddBasketItem): Promise<BasketResult>;
22	  updateItem(id: string, productId: string, quantity: number): Promise<BasketResult>;
23	  removeItem(id: string, productId: string): Promise<BasketResult>;
24	  clear(id: string): Promise<BasketResponse>;
25	}
26	
27	const NO_ITEMS: StoredBasket["items"] = [];
28	
29	export function createBasketService({ store, catalog, now }: BasketServiceOptions): BasketService {
30	  const timestamp = () => new Date(now()).toISOString();
31	
32	  /** Joins every stored line with the catalog; totals ignore lines whose product is gone. */
33	  async function toResponse(id: string, stored: StoredBasket | undefined): Promise<BasketResponse> {
34	    const items: BasketLine[] = await Promise.all(
35	      (stored?.items ?? []).map(async (line) => ({
36	        productId: line.productId,
37	        quantity: line.quantity,
38	        product: (await catalog.findProduct(line.productId)) ?? null,
39	      })),
40	    );
41	    const totals = items.reduce(
42	      (acc, line) =>
43	        line.product
44	          ? { count: acc.count + line.quantity, sum: acc.sum + line.product.price * line.quantity }
45	          : acc,
46	      { count: 0, sum: 0 },
47	    );
48	    return { id, items, totals };
49	  }
50	
51	  return {
52	    // A GET never creates a file entry: an unknown id simply reads as the empty basket.
53	    async get(id) {
54	      return toResponse(id, await store.get(id));
55	    },
56	
57	    async addItem(id, { productId, quantity }) {
58	      // Resolved before the write, so a 404 leaves the basket untouched.
59	      const product = await catalog.findProduct(productId);
60	      if (!product) return { ok: false, error: "Product not found" };
61	      const updatedAt = timestamp();
62	      const stored = await store.update(id, (current) => {
63	        const items = current?.items ?? NO_ITEMS;
64	        const existing = items.find((line) => line.productId === productId);
65	        return {
66	          updatedAt,
67	          items: existing
68	            ? items.map((line) =>
69	                line.productId === productId
70	                  ? { ...line, quantity: Math.min(MAX_QUANTITY, line.quantity + quantity) }
71	                  : line,
72	              )
73	            : [...items, { productId, quantity, addedAt: updatedAt }],
74	        };
75	      });
76	      return { ok: true, basket: await toResponse(id, stored) };
77	    },
78	
79	    async updateItem(id, productId, quantity) {
80	      const current = await store.get(id);
81	      if (!current?.items.some((line) => line.productId === productId)) {
82	        return { ok: false, error: "Basket item not found" };
83	      }
84	      const updatedAt = timestamp();
85	      const stored = await store.update(id, (basket) => ({
86	        updatedAt,
87	        items: (basket?.items ?? NO_ITEMS).map((line) =>
88	          line.productId === productId ? { ...line, quantity } : line,
89	        ),
90	      }));
91	      return { ok: true, basket: await toResponse(id, stored) };
92	    },
93	
94	    async removeItem(id, productId) {
95	      const current = await store.get(id);
96	      if (!current?.items.some((line) => line.productId === productId)) {
97	        return { ok: false, error: "Basket item not found" };
98	      }
99	      const updatedAt = timestamp();
100	      const stored = await store.update(id, (basket) => ({
101	        updatedAt,
102	        items: (basket?.items ?? NO_ITEMS).filter((line) => line.productId !== productId),
103	      }));
104	      return { ok: true, basket: await toResponse(id, stored) };
105	    },
106	
107	    async clear(id) {
108	      const stored = await store.update(id, () => ({ updatedAt: timestamp(), items: [] }));
109	      return toResponse(id, stored);
110	    },
111	  };
112	}
