 1	import { readFile } from "node:fs/promises";
 2	import { join } from "node:path";
 3	import { SHOPS, SnapshotFileSchema, type Product, type ShopKey } from "@organic/shared";
 4	
 5	export interface SnapshotSource {
 6	  read(key: ShopKey): Promise<Product[]>;
 7	}
 8	
 9	async function readSnapshot(dir: string, key: ShopKey): Promise<Product[]> {
10	  const file = SnapshotFileSchema.parse(JSON.parse(await readFile(join(dir, `${key}.json`), "utf8")));
11	  return file.products.map((product) => ({
12	    ...product,
13	    id: `${key}:${product.sourceId}`,
14	    shopKey: key,
15	    shopName: SHOPS[key].name,
16	  }));
17	}
18	
19	/** Reads the committed snapshots from a directory passed as a value — never from the environment. */
20	export function createSnapshotSource(dir: string): SnapshotSource {
21	  const pending = new Map<ShopKey, Promise<Product[]>>();
22	  return {
23	    read(key) {
24	      const memoized = pending.get(key);
25	      if (memoized) return memoized;
26	      // A rejection is never memoized: a snapshot written after a failed read is picked up on the next call.
27	      const started = readSnapshot(dir, key).catch((error: unknown) => {
28	        pending.delete(key);
29	        throw error;
30	      });
31	      pending.set(key, started);
32	      return started;
33	    },
34	  };
35	}

